<?php
declare(strict_types=1);
require is_file(__DIR__.'/../vendor/autoload.php')?__DIR__.'/../vendor/autoload.php':getcwd().'/vendor/autoload.php';
require __DIR__.'/../examples/extension/src/ExampleProvider.php';
require __DIR__.'/../examples/extension/src/ExampleSourceAdapter.php';
use VHUG\SchemaManagerBundle\Extension\V1 as Api;
use VHUG\SchemaManagerBundle\Extension\Internal as Internal;
$checks=0;
$check=static function(bool $ok,string $why)use(&$checks){if(!$ok)throw new RuntimeException($why);$checks++;};
$reject=static function(callable $action,string $why)use($check){try{$action();}catch(LogicException|InvalidArgumentException $e){$check(true,$why);return;}$check(false,$why);};
$provider=new SchemaManagerExample\ExampleProvider();
$registry=new Internal\Registry([$provider],[$provider],[],[get_class($provider)=>$provider]);
$check(count($registry->types())===1 && count($registry->relationships())===2,'Registry accepts independent providers.');
$reject(fn()=>new Internal\Registry([$provider,$provider],[],[],[get_class($provider)=>$provider]),'Duplicate types rejected.');
$reject(fn()=>new Internal\Registry([$provider],[$provider],[],[]),'Missing mapper rejected.');
$reject(fn()=>new Api\ReadContext('preview','1','de'),'Preview requires an actor.');
$reject(fn()=>new Api\CandidateQuery(new Api\ReadContext('discovery','1','de',1,true),limit:101),'Candidate budget enforced.');
$one=new Api\SourceReference('example.inventory','1','a|b');
$two=new Api\SourceReference('example.inventory','1|a','b');
$check($one->key()!==$two->key(),'Source tuple hashing is unambiguous.');
$fields=new Internal\FieldValidator();$type=$registry->type('example.equipment');
$values=$fields->validate($type,['name'=>'Equipment','capacity'=>['value'=>'135.31','unit'=>'MTK','basis'=>'DIN 277 net area']],['description'=>'Localized']);
$check($values['capacity']['value']==='135.31','Decimal precision and measurement basis retained.');
$reject(fn()=>$fields->validate($type,['name'=>'Equipment','capacity'=>['value'=>'1','unit'=>'MTK']],[]),'Basis required.');
$reject(fn()=>$fields->validate($type,['name'=>'Equipment','description'=>'Wrong scope'],[]),'Wrong field scope rejected.');
$reject(fn()=>Internal\Vocabulary::property(['Product'],'seller',['Organization']),'Seller cannot be emitted on Product.');
$reject(fn()=>Internal\Vocabulary::property(['Product'],'manufacturer',['Person']),'Invalid target range rejected.');
$reject(fn()=>Internal\Vocabulary::property(['Product'],'displayLocation',['Place']),'Pending vocabulary needs approval.');
Internal\Vocabulary::property(['Product'],'displayLocation',['Place'],true);
$check(true,'Explicit pending declaration works.');
$mapped=$provider->map(new Api\ResolvedEntity(new Api\EntityReference(1),'https://example.org/#one',$type,$values,[],null),new Api\MappingContext(new Api\ReadContext('frontend','1','de')));
Internal\Vocabulary::node($type->schemaTypes,$mapped->properties);
$check($mapped->properties['additionalProperty']['name']==='DIN 277 net area','Mapper uses reusable typed measurement builder.');
$node=new Internal\JsonLdType(['@id'=>'https://example.org/#one','@type'=>'ProductModel']+$mapped->properties);
$graph=new Spatie\SchemaOrg\Graph();$graph->set($node,'one');
$check($graph->toArray()['@graph'][0]['@type']==='ProductModel','Generic vocabulary bridge works with Spatie graph.');
$reject(fn()=>new Api\SourceResolution('missing',new Api\SourceSnapshot($one,'1','example.equipment',[],[])),'Unavailable resolution cannot carry facts.');

$check(Internal\Store::decode(Internal\Store::encode(['target'=>new Api\EntityReference(7)]))['target']->id===7,'Managed reference payload round trip retains typed identity.');
$reject(fn()=>Internal\Vocabulary::node(['Product'],['manufacturer'=>['@id'=>'https://example.org/#unresolved']]),'Unresolved mapper references rejected.');
$capabilities=new class implements Api\RelationshipProviderInterface { public function relationships():iterable{yield new Api\RelationshipDefinition('example.capability','Manufacturer',['capability:product'],['capability:organization'],property:'manufacturer');} };
$expanded=new Internal\Registry([$provider],[$provider,$capabilities],[],[get_class($provider)=>$provider]);
$check($expanded->relationship('example.capability')->sourceTypes===['Product'] && in_array('LocalBusiness',$expanded->relationship('example.capability')->targetTypes,true),'Capability selectors expand and validate all concrete endpoints.');
$requiredList=new Api\TypeDefinition('example.list','Required list',['ProductModel'],get_class($provider),fields:[new Api\FieldDefinition('items',multiple:true,required:true)]);
$reject(fn()=>$fields->validate($requiredList,['items'=>[]],[]),'Required repeated fields reject empty lists.');
Internal\Vocabulary::property(['ProductModel'],'displayLocation',['House','Product'],true);
$check(true,'A multi-typed target satisfies a range when one of its types is a permitted subtype.');
$reject(fn()=>Internal\Vocabulary::property(['ProductModel'],'displayLocation',['Person','Organization'],true),'Multi-typing cannot satisfy a range with unrelated types.');
$check((new Api\SourceDefinition(['Person']))->automatic===false,'Existing adapters retain their supplementary editing workflow.');
$check((new Api\SourceDefinition(['Person'],automatic:true))->automatic,'Automatic source ownership is an explicit adapter capability.');
echo 'PASS: '.$checks." extension registry, ownership shapes, vocabulary and graph checks\n";
